-- ============================================================================
-- docs/script.sql | MODELO DIDATICO DE UM RESTAURANTE DE PEQUENO PORTE
-- Compatibilidade-alvo: MySQL 8.0.16+ (CHECK efetivo a partir de 8.0.16)
-- Gerado com dados 100% ficticios. Nao utilizar dados reais da organizacao.
-- IMPORTANTE: P01-P05, KPI01-KPI10 e RN01-RN15 sao CODIGOS PROVISORIOS.
-- Substituir pelos codigos confirmados do levantamento e do modelo DER do grupo.
-- Base ilustrativa: 900 pedidos em 90 dias (10/dia), 60 clientes e 16 produtos.
-- Nao representa dados verificados da organizacao; conferir secao 1.1.
-- ATENCAO: o comando DROP DATABASE abaixo APAGA um banco com este nome.
-- Execute apenas no ambiente academico de teste, nunca em producao.
-- ============================================================================

-- SECAO 1 - CREATE DATABASE (recria ambiente de demonstracao do zero)
DROP DATABASE IF EXISTS restaurante_academico_demo;
CREATE DATABASE restaurante_academico_demo
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE restaurante_academico_demo;

-- SECAO 2 - CREATE TABLE (esquema relacional)
-- SECAO 3 - CONSTRAINTS (PK, FK, NOT NULL, UNIQUE, CHECK e DEFAULT inline)
-- RN01: estoque nao negativo e estoque minimo nao negativo.
-- RN02: preco e custo unitario de produto maiores/iguais a zero, preco > 0.
-- RN03: entrega requer cliente/endereco; pedidos presenciais sem endereco.
-- RN04: todo pedido deve ter um ou mais itens (ver auditoria A02).
-- RN05: quantidade e preco de item positivos; item unico por produto/pedido.
-- RN06: total = soma de itens + entrega - desconto (ver A04).
-- RN07: pedido concluido deve ter pagamentos APROVADOS = total (ver A05).
-- RN08: cancelados nao podem ter pagamentos APROVADOS; estornos apenas neles.
-- RN09: saldo estoque deve corresponder a entradas menos saidas (ver A07).
-- RN10: baixa de estoque deve refletir itens de pedidos concluidos.
-- RN11: pagamento PENDENTE nao pode pertencer a pedido CONCLUIDO.
-- RN12: endereco deve pertencer ao cliente do pedido (FK composta).
-- RN13: desconto deve ser autorizado por GERENTE.
-- RN14: cancelamento deve ser autorizado por GERENTE.
-- RN15: valores nao negativos e integridade das informacoes essenciais.

CREATE TABLE clientes (
  id_cliente INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(120) NOT NULL,
  telefone VARCHAR(20) NULL UNIQUE,
  email VARCHAR(180) NULL UNIQUE,
  cadastrado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ativo TINYINT(1) NOT NULL DEFAULT 1,
  CONSTRAINT ck_cliente_nome CHECK (CHAR_LENGTH(TRIM(nome)) >= 3),
  CONSTRAINT ck_cliente_ativo CHECK (ativo IN (0,1))
) ENGINE=InnoDB;

CREATE TABLE enderecos (
  id_endereco INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_cliente INT UNSIGNED NOT NULL,
  cep CHAR(9) NOT NULL,
  logradouro VARCHAR(140) NOT NULL,
  numero VARCHAR(12) NOT NULL,
  bairro VARCHAR(100) NOT NULL,
  cidade VARCHAR(100) NOT NULL DEFAULT 'Sao Paulo',
  uf CHAR(2) NOT NULL DEFAULT 'SP',
  principal TINYINT(1) NOT NULL DEFAULT 0,
  CONSTRAINT uq_endereco_cliente UNIQUE(id_cliente,id_endereco),
  CONSTRAINT fk_endereco_cliente FOREIGN KEY (id_cliente) REFERENCES clientes(id_cliente),
  CONSTRAINT ck_endereco_principal CHECK (principal IN (0,1))
) ENGINE=InnoDB;

CREATE TABLE usuarios_sistema (
  id_usuario INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(100) NOT NULL,
  perfil ENUM('GERENTE','ATENDENTE','FINANCEIRO') NOT NULL,
  ativo TINYINT(1) NOT NULL DEFAULT 1,
  CONSTRAINT ck_usuario_ativo CHECK (ativo IN (0,1))
) ENGINE=InnoDB;

CREATE TABLE categorias (
  id_categoria INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(90) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE produtos (
  id_produto INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_categoria INT UNSIGNED NOT NULL,
  sku VARCHAR(24) NOT NULL UNIQUE,
  nome VARCHAR(140) NOT NULL UNIQUE,
  preco_venda DECIMAL(10,2) NOT NULL,
  custo_unitario DECIMAL(10,2) NOT NULL,
  estoque_atual INT NOT NULL DEFAULT 0,
  estoque_minimo INT NOT NULL DEFAULT 0,
  ativo TINYINT(1) NOT NULL DEFAULT 1,
  CONSTRAINT fk_produto_categoria FOREIGN KEY (id_categoria) REFERENCES categorias(id_categoria),
  CONSTRAINT ck_produto_preco CHECK (preco_venda > 0),
  CONSTRAINT ck_produto_custo CHECK (custo_unitario >= 0),
  CONSTRAINT ck_produto_estoque CHECK (estoque_atual >= 0 AND estoque_minimo >= 0),
  CONSTRAINT ck_produto_ativo CHECK (ativo IN (0,1))
) ENGINE=InnoDB;

CREATE TABLE canais_venda (
  id_canal INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(70) NOT NULL UNIQUE,
  tipo ENUM('PRESENCIAL','DELIVERY') NOT NULL,
  taxa_percentual DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  CONSTRAINT ck_canal_taxa CHECK (taxa_percentual BETWEEN 0 AND 40)
) ENGINE=InnoDB;

CREATE TABLE pedidos (
  id_pedido INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_cliente INT UNSIGNED NULL,
  id_endereco INT UNSIGNED NULL,
  id_canal INT UNSIGNED NOT NULL,
  data_pedido DATETIME NOT NULL,
  status ENUM('ABERTO','CONCLUIDO','CANCELADO') NOT NULL DEFAULT 'ABERTO',
  desconto DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  taxa_entrega DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  total DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  id_autorizador_desconto INT UNSIGNED NULL,
  id_autorizador_cancelamento INT UNSIGNED NULL,
  cancelado_em DATETIME NULL,
  observacao VARCHAR(250) NULL,
  CONSTRAINT fk_pedido_cliente FOREIGN KEY (id_cliente) REFERENCES clientes(id_cliente),
  CONSTRAINT fk_pedido_canal FOREIGN KEY (id_canal) REFERENCES canais_venda(id_canal),
  CONSTRAINT fk_pedido_endereco_cliente FOREIGN KEY (id_cliente,id_endereco)
      REFERENCES enderecos(id_cliente,id_endereco),
  CONSTRAINT fk_pedido_aut_desconto FOREIGN KEY (id_autorizador_desconto) REFERENCES usuarios_sistema(id_usuario),
  CONSTRAINT fk_pedido_aut_cancel FOREIGN KEY (id_autorizador_cancelamento) REFERENCES usuarios_sistema(id_usuario),
  CONSTRAINT ck_pedido_valores CHECK (desconto >= 0 AND taxa_entrega >= 0 AND total >= 0),
  CONSTRAINT ck_pedido_cancelado CHECK
    ((status = 'CANCELADO' AND cancelado_em IS NOT NULL) OR
     (status <> 'CANCELADO' AND cancelado_em IS NULL)),
  CONSTRAINT ck_pedido_autorizacoes CHECK
    ((desconto = 0 OR id_autorizador_desconto IS NOT NULL) AND
     (status <> 'CANCELADO' OR id_autorizador_cancelamento IS NOT NULL))
) ENGINE=InnoDB;
CREATE INDEX idx_pedidos_data_status ON pedidos(data_pedido,status);
CREATE INDEX idx_pedidos_canal_data ON pedidos(id_canal,data_pedido);

CREATE TABLE itens_pedido (
  id_item INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_pedido INT UNSIGNED NOT NULL,
  id_produto INT UNSIGNED NOT NULL,
  quantidade SMALLINT UNSIGNED NOT NULL,
  preco_unitario DECIMAL(10,2) NOT NULL,
  custo_unitario DECIMAL(10,2) NOT NULL,
  subtotal DECIMAL(12,2) GENERATED ALWAYS AS (quantidade * preco_unitario) STORED,
  CONSTRAINT uq_item_produto_pedido UNIQUE (id_pedido,id_produto),
  CONSTRAINT fk_item_pedido FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
  CONSTRAINT fk_item_produto FOREIGN KEY (id_produto) REFERENCES produtos(id_produto),
  CONSTRAINT ck_item_qtd CHECK (quantidade > 0),
  CONSTRAINT ck_item_preco CHECK (preco_unitario > 0 AND custo_unitario >= 0)
) ENGINE=InnoDB;

CREATE TABLE pagamentos (
  id_pagamento INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_pedido INT UNSIGNED NOT NULL,
  forma ENUM('PIX','DINHEIRO','CARTAO_CREDITO','CARTAO_DEBITO','VALE_REFEICAO') NOT NULL,
  status ENUM('APROVADO','PENDENTE','ESTORNADO','RECUSADO') NOT NULL,
  valor DECIMAL(10,2) NOT NULL,
  data_pagamento DATETIME NOT NULL,
  codigo_transacao VARCHAR(80) NULL UNIQUE,
  CONSTRAINT fk_pagamento_pedido FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
  CONSTRAINT ck_pagamento_valor CHECK (valor > 0)
) ENGINE=InnoDB;
CREATE INDEX idx_pagamento_status_data ON pagamentos(status,data_pagamento);

CREATE TABLE movimentacoes_estoque (
  id_movimentacao INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_produto INT UNSIGNED NOT NULL,
  id_pedido INT UNSIGNED NULL,
  tipo ENUM('ENTRADA','SAIDA') NOT NULL,
  quantidade INT NOT NULL,
  data_movimentacao DATETIME NOT NULL,
  motivo VARCHAR(150) NOT NULL,
  CONSTRAINT fk_mov_produto FOREIGN KEY (id_produto) REFERENCES produtos(id_produto),
  CONSTRAINT fk_mov_pedido FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
  CONSTRAINT ck_mov_quantidade CHECK (quantidade > 0),
  CONSTRAINT ck_mov_origem CHECK
    ((tipo='ENTRADA' AND id_pedido IS NULL) OR (tipo='SAIDA' AND id_pedido IS NOT NULL))
) ENGINE=InnoDB;
CREATE INDEX idx_mov_produto_data ON movimentacoes_estoque(id_produto,data_movimentacao);
CREATE INDEX idx_mov_pedido_produto ON movimentacoes_estoque(id_pedido,id_produto);

CREATE TABLE despesas (
  id_despesa INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  categoria ENUM('INSUMOS','SALARIOS','ALUGUEL','ENERGIA','AGUA','MARKETING','OUTROS') NOT NULL,
  descricao VARCHAR(160) NOT NULL,
  valor DECIMAL(10,2) NOT NULL,
  vencimento DATE NOT NULL,
  pago TINYINT(1) NOT NULL DEFAULT 0,
  CONSTRAINT ck_despesa_valor CHECK (valor > 0),
  CONSTRAINT ck_despesa_pago CHECK (pago IN (0,1))
) ENGINE=InnoDB;
CREATE INDEX idx_despesa_vencimento ON despesas(vencimento);

