COMMIT;

-- SECAO 5 - SELECT COM JOIN (relacionamento de multiplas tabelas)
-- J01: pedidos com cliente, canal e endereco (quando aplicavel).
SELECT p.id_pedido,p.data_pedido,COALESCE(cl.nome,'Consumidor nao identificado') AS cliente,
       cv.nome AS canal, cv.tipo, e.logradouro, p.status, p.total
FROM pedidos p
LEFT JOIN clientes cl ON cl.id_cliente=p.id_cliente
JOIN canais_venda cv ON cv.id_canal=p.id_canal
LEFT JOIN enderecos e ON e.id_endereco=p.id_endereco
ORDER BY p.id_pedido LIMIT 20;

-- J02: detalhes dos itens vendidos, com categoria e produto.
SELECT p.id_pedido,p.data_pedido,pr.nome AS produto,ct.nome AS categoria,
       ip.quantidade,ip.preco_unitario,ip.subtotal
FROM itens_pedido ip
JOIN pedidos p ON p.id_pedido=ip.id_pedido
JOIN produtos pr ON pr.id_produto=ip.id_produto
JOIN categorias ct ON ct.id_categoria=pr.id_categoria
WHERE p.status='CONCLUIDO'
ORDER BY p.data_pedido,ip.id_item LIMIT 20;

-- SECAO 6 - UPDATE (alteracao real, sem violar FKs/constraints)
-- Exemplo: cliente ficticio atualiza seu telefone.
UPDATE clientes SET telefone='11900009060' WHERE id_cliente=60;

-- SECAO 7 - DELETE (registro de teste sem dependencias)
INSERT INTO despesas (categoria,descricao,valor,vencimento,pago)
VALUES ('OUTROS','REGISTRO TEMPORARIO PARA EXCLUSAO',1.00,'2026-10-30',0);
DELETE FROM despesas WHERE descricao='REGISTRO TEMPORARIO PARA EXCLUSAO';

-- SECAO 8 - CONSULTAS GERENCIAIS (Gxx: problema + KPI)
-- NOTA: Pxx/KPIxx sao HIPOTESES DIDATICAS ate o grupo validar 1.1 e 1.6.

-- G01 — Qual foi o faturamento mensal dos pedidos concluidos e a receita apos taxas de canal?
-- Atende: P02 (falta de visao de faturamento); KPI01 (faturamento), KPI02 (receita apos taxas).
SELECT DATE_FORMAT(p.data_pedido,'%Y-%m') AS mes,
       COUNT(*) AS pedidos_concluidos,
       ROUND(SUM(p.total),2) AS faturamento,
       ROUND(SUM(p.total*cv.taxa_percentual/100),2) AS taxas_estimadas,
       ROUND(SUM(p.total*(100-cv.taxa_percentual)/100.0),2) AS receita_apos_taxas
FROM pedidos p JOIN canais_venda cv ON cv.id_canal=p.id_canal
WHERE p.status='CONCLUIDO'
GROUP BY DATE_FORMAT(p.data_pedido,'%Y-%m') ORDER BY mes;

-- G02 — Quantos pedidos foram concluidos por mes e qual foi o ticket medio?
-- Atende: P02 (dificuldade de acompanhar vendas); KPI03 (pedidos concluídos), KPI04 (ticket medio).
SELECT DATE_FORMAT(data_pedido,'%Y-%m') AS mes,COUNT(*) AS quantidade,
       ROUND(AVG(total),2) AS ticket_medio
FROM pedidos WHERE status='CONCLUIDO'
GROUP BY DATE_FORMAT(data_pedido,'%Y-%m') ORDER BY mes;

-- G03 — Quais produtos estao abaixo do estoque minimo?
-- Atende: P01 (ruptura de estoque); KPI05 (itens abaixo do minimo).
SELECT id_produto,sku,nome,estoque_atual,estoque_minimo,
       estoque_minimo-estoque_atual AS unidades_para_repor
FROM produtos WHERE ativo=1 AND estoque_atual<estoque_minimo
ORDER BY unidades_para_repor DESC,nome;

-- G04 — Quais sao os produtos mais vendidos em quantidade e receita?
-- Atende: P05 (desconhecimento do mix de produtos); KPI06 (ranking de vendas).
SELECT pr.id_produto,pr.nome, SUM(ip.quantidade) AS unidades,
       ROUND(SUM(ip.subtotal),2) AS receita_itens
FROM itens_pedido ip JOIN pedidos p ON p.id_pedido=ip.id_pedido
JOIN produtos pr ON pr.id_produto=ip.id_produto
WHERE p.status='CONCLUIDO'
GROUP BY pr.id_produto,pr.nome ORDER BY unidades DESC,receita_itens DESC;

-- G05 — Qual canal gera mais vendas e quanto cobra de taxa estimada?
-- Atende: P03 (falta de analise dos canais); KPI07 (vendas por canal).
SELECT cv.nome AS canal,COUNT(*) AS pedidos,
       ROUND(SUM(p.total),2) AS faturamento,
       ROUND(SUM(p.total*cv.taxa_percentual/100),2) AS taxa_estimada
FROM pedidos p JOIN canais_venda cv ON cv.id_canal=p.id_canal
WHERE p.status='CONCLUIDO'
GROUP BY cv.id_canal,cv.nome ORDER BY faturamento DESC;

-- G06 — Quais foram os percentuais de cancelamento por mes?
-- Atende: P04 (falta de controle de cancelamentos); KPI08 (taxa de cancelamento).
SELECT DATE_FORMAT(data_pedido,'%Y-%m') AS mes,COUNT(*) AS pedidos_totais,
       SUM(CASE WHEN status='CANCELADO' THEN 1 ELSE 0 END) AS cancelados,
       ROUND(100*SUM(CASE WHEN status='CANCELADO' THEN 1 ELSE 0 END)/COUNT(*),2) AS taxa_cancelamento_pct
FROM pedidos GROUP BY DATE_FORMAT(data_pedido,'%Y-%m') ORDER BY mes;

-- G07 — Quanto foi arrecadado por forma de pagamento?
-- Atende: P03 (controle dos recebimentos); KPI09 (arrecadacao por forma de pagamento).
SELECT forma,COUNT(*) AS transacoes_aprovadas,ROUND(SUM(valor),2) AS valor_aprovado
FROM pagamentos WHERE status='APROVADO'
GROUP BY forma ORDER BY valor_aprovado DESC;

-- G08 — Quais pedidos estao abertos e que pagamentos continuam pendentes?
-- Atende: P03 (acompanhamento de pagamentos); KPI10 (pedidos em aberto).
SELECT p.id_pedido,p.data_pedido,p.total,p.status,
       COUNT(pg.id_pagamento) AS tentativas_pagamento,
       COALESCE(SUM(CASE WHEN pg.status='PENDENTE' THEN pg.valor ELSE 0 END),0) AS valor_pendente
FROM pedidos p LEFT JOIN pagamentos pg ON pg.id_pedido=p.id_pedido
WHERE p.status='ABERTO'
GROUP BY p.id_pedido,p.data_pedido,p.total,p.status ORDER BY p.data_pedido;

-- G09 — Quais produtos geram maior margem de contribuicao bruta antes de despesas fixas?
-- Atende: P05 (margem desconhecida); KPI11 (margem por produto).
SELECT pr.nome,SUM(ip.quantidade) AS unidades,
       ROUND(SUM(ip.quantidade*ip.preco_unitario),2) AS faturamento_itens,
       ROUND(SUM(ip.quantidade*ip.custo_unitario),2) AS custo_dos_itens,
       ROUND(SUM(ip.quantidade*(ip.preco_unitario-ip.custo_unitario)),2) AS margem_bruta_itens
FROM itens_pedido ip JOIN pedidos p ON p.id_pedido=ip.id_pedido
JOIN produtos pr ON pr.id_produto=ip.id_produto
WHERE p.status='CONCLUIDO'
GROUP BY pr.id_produto,pr.nome ORDER BY margem_bruta_itens DESC;

-- G10 — Qual resultado operacional estimado por mes apos custo vendido, taxa de canal e despesas nao-insumos?
-- Atende: P02 e P05 (visao gerencial de resultado); KPI12 (resultado operacional estimado).
-- Compras classificadas como INSUMOS sao excluidas das despesas aqui para evitar
-- dupla contagem do custo dos itens vendidos reconhecido em itens_pedido.
-- A taxa sobre total do pedido e simplificacao didatica; validar contrato real.
WITH v AS (
 SELECT DATE_FORMAT(p.data_pedido,'%Y-%m') AS mes,
        SUM(p.total) AS receita,
        SUM(p.total*cv.taxa_percentual/100) AS taxa_canais
 FROM pedidos p JOIN canais_venda cv ON cv.id_canal=p.id_canal
 WHERE p.status='CONCLUIDO' GROUP BY DATE_FORMAT(p.data_pedido,'%Y-%m')
), c AS (
 SELECT DATE_FORMAT(p.data_pedido,'%Y-%m') AS mes,
        SUM(ip.quantidade*ip.custo_unitario) AS cmv
 FROM itens_pedido ip JOIN pedidos p ON p.id_pedido=ip.id_pedido
 WHERE p.status='CONCLUIDO' GROUP BY DATE_FORMAT(p.data_pedido,'%Y-%m')
), d AS (
 SELECT DATE_FORMAT(vencimento,'%Y-%m') AS mes,SUM(valor) AS outras_despesas
 FROM despesas WHERE categoria<>'INSUMOS'
 GROUP BY DATE_FORMAT(vencimento,'%Y-%m')
)
SELECT v.mes,ROUND(v.receita,2) AS receita,ROUND(v.taxa_canais,2) AS taxas,
       ROUND(COALESCE(c.cmv,0),2) AS cmv,
       ROUND(COALESCE(d.outras_despesas,0),2) AS outras_despesas,
       ROUND(v.receita-v.taxa_canais-COALESCE(c.cmv,0)-COALESCE(d.outras_despesas,0),2) AS resultado_estimado
FROM v LEFT JOIN c ON c.mes=v.mes LEFT JOIN d ON d.mes=v.mes ORDER BY v.mes;

-- G11 — Quais clientes cadastrados nao tiveram pedido concluido?
-- Atende: P02 (relacionamento e fidelizacao); KPI13 (clientes sem compra efetiva).
SELECT cl.id_cliente,cl.nome,cl.email
FROM clientes cl LEFT JOIN pedidos p ON p.id_cliente=cl.id_cliente AND p.status='CONCLUIDO'
WHERE p.id_pedido IS NULL ORDER BY cl.id_cliente;

-- G12 — Quantos pedidos usaram mais de uma forma/parcela de pagamento aprovado?
-- Atende: P03 (conciliacao de pagamentos multiplos); KPI14 (pedidos com pagamento dividido).
SELECT p.id_pedido,p.total,COUNT(pg.id_pagamento) AS parcelas,
       ROUND(SUM(pg.valor),2) AS valor_aprovado
FROM pedidos p JOIN pagamentos pg ON pg.id_pedido=p.id_pedido AND pg.status='APROVADO'
WHERE p.status='CONCLUIDO'
GROUP BY p.id_pedido,p.total HAVING COUNT(pg.id_pagamento)>1 ORDER BY p.id_pedido;

-- G13 — Quantos pedidos cancelados tiveram estorno registrado?
-- Atende: P04 (reembolso e cancelamentos); KPI15 (estornos por cancelamento).
SELECT p.id_pedido,p.data_pedido,ROUND(SUM(pg.valor),2) AS valor_estornado
FROM pedidos p JOIN pagamentos pg ON pg.id_pedido=p.id_pedido
WHERE p.status='CANCELADO' AND pg.status='ESTORNADO'
GROUP BY p.id_pedido,p.data_pedido ORDER BY p.data_pedido;

-- SECAO 9 - CONSULTAS DE AUDITORIA (Axx: verificam regras RNxx)
-- Convencao: cada SELECT retorna SOMENTE ANOMALIAS; zero linhas = nenhum achado.

-- A01 — Ha produtos com estoque negativo ou abaixo de zero permitido?
-- Verifica: RN01 (estoque nao negativo e minimo valido).
SELECT id_produto,nome,estoque_atual,estoque_minimo FROM produtos
WHERE estoque_atual<0 OR estoque_minimo<0;

-- A02 — Existe pedido sem qualquer item?
-- Verifica: RN04 (todo pedido deve conter itens).
SELECT p.id_pedido,p.status FROM pedidos p
LEFT JOIN itens_pedido ip ON ip.id_pedido=p.id_pedido
GROUP BY p.id_pedido,p.status HAVING COUNT(ip.id_item)=0;

-- A03 — Existe item invalido ou produto repetido no mesmo pedido?
-- Verifica: RN05 (quantidade/preco positivo e unicidade por produto/pedido).
SELECT id_pedido,id_produto,COUNT(*) AS repeticoes,
       MIN(quantidade) AS menor_quantidade,MIN(preco_unitario) AS menor_preco
FROM itens_pedido GROUP BY id_pedido,id_produto
HAVING COUNT(*)>1 OR MIN(quantidade)<=0 OR MIN(preco_unitario)<=0;

-- A04 — O total do pedido confere com os itens, entrega e desconto?
-- Verifica: RN06 (consistencia aritmetica do total).
SELECT p.id_pedido,p.total,
       ROUND(COALESCE(SUM(ip.subtotal),0)+p.taxa_entrega-p.desconto,2) AS total_calculado
FROM pedidos p LEFT JOIN itens_pedido ip ON ip.id_pedido=p.id_pedido
GROUP BY p.id_pedido,p.total,p.taxa_entrega,p.desconto
HAVING ABS(p.total-(COALESCE(SUM(ip.subtotal),0)+p.taxa_entrega-p.desconto))>0.009;

-- A05 — Ha pedido concluido cujo pagamento aprovado difere do total?
-- Verifica: RN07 (conciliacao integral de pagamentos concluidos).
SELECT p.id_pedido,p.total,
       ROUND(COALESCE(SUM(CASE WHEN pg.status='APROVADO' THEN pg.valor ELSE 0 END),0),2) AS pago
FROM pedidos p LEFT JOIN pagamentos pg ON pg.id_pedido=p.id_pedido
WHERE p.status='CONCLUIDO'
GROUP BY p.id_pedido,p.total
HAVING ABS(p.total-COALESCE(SUM(CASE WHEN pg.status='APROVADO' THEN pg.valor ELSE 0 END),0))>0.009;

-- A06 — Ha pagamento aprovado em cancelado ou estorno de nao cancelado?
-- Verifica: RN08 (consistencia do cancelamento/reembolso).
SELECT pg.id_pagamento,pg.id_pedido,p.status AS status_pedido,pg.status AS status_pagamento
FROM pagamentos pg JOIN pedidos p ON p.id_pedido=pg.id_pedido
WHERE (p.status='CANCELADO' AND pg.status='APROVADO')
   OR (p.status<>'CANCELADO' AND pg.status='ESTORNADO');

-- A07 — O saldo registrado de cada produto difere de entradas menos saidas?
-- Verifica: RN09 (reconciliacao fisico-logica do estoque).
SELECT pr.id_produto,pr.nome,pr.estoque_atual,
       COALESCE(SUM(CASE WHEN mv.tipo='ENTRADA' THEN mv.quantidade ELSE -mv.quantidade END),0) AS saldo_movimentos
FROM produtos pr LEFT JOIN movimentacoes_estoque mv ON mv.id_produto=pr.id_produto
GROUP BY pr.id_produto,pr.nome,pr.estoque_atual
HAVING pr.estoque_atual<>COALESCE(SUM(CASE WHEN mv.tipo='ENTRADA' THEN mv.quantidade ELSE -mv.quantidade END),0);

-- A08 — Algum item concluido nao possui a quantidade equivalente de baixa em estoque?
-- Verifica: RN10 (baixa corresponde a cada produto vendido em pedido concluido).
SELECT ip.id_pedido,ip.id_produto,ip.quantidade,
       COALESCE(SUM(mv.quantidade),0) AS quantidade_baixada
FROM itens_pedido ip JOIN pedidos p ON p.id_pedido=ip.id_pedido
LEFT JOIN movimentacoes_estoque mv ON mv.id_pedido=ip.id_pedido
  AND mv.id_produto=ip.id_produto AND mv.tipo='SAIDA'
WHERE p.status='CONCLUIDO'
GROUP BY ip.id_pedido,ip.id_produto,ip.quantidade
HAVING ip.quantidade<>COALESCE(SUM(mv.quantidade),0);

-- A09 — Existem baixas para pedido nao concluido ou produto nao presente no pedido?
-- Verifica: RN10 (nao baixar cancelados/abertos nem produtos alheios).
SELECT mv.id_movimentacao,mv.id_pedido,mv.id_produto,p.status
FROM movimentacoes_estoque mv
JOIN pedidos p ON p.id_pedido=mv.id_pedido
LEFT JOIN itens_pedido ip ON ip.id_pedido=mv.id_pedido AND ip.id_produto=mv.id_produto
WHERE mv.tipo='SAIDA' AND (p.status<>'CONCLUIDO' OR ip.id_item IS NULL);

-- A10 — Existe pagamento pendente atrelado a pedido concluido?
-- Verifica: RN11 (nao concluir sem efetivar pagamento).
SELECT pg.id_pagamento,pg.id_pedido,pg.status
FROM pagamentos pg JOIN pedidos p ON p.id_pedido=pg.id_pedido
WHERE p.status='CONCLUIDO' AND pg.status='PENDENTE';

-- A11 — Existe entrega sem endereco/cliente, pedido presencial com endereco,
--        ou endereco de cliente diferente?
-- Verifica: RN03 e RN12 (endereco obrigatorio e titularidade).
SELECT p.id_pedido,cv.tipo,p.id_cliente,p.id_endereco,e.id_cliente AS dono_endereco
FROM pedidos p JOIN canais_venda cv ON cv.id_canal=p.id_canal
LEFT JOIN enderecos e ON e.id_endereco=p.id_endereco
WHERE (cv.tipo='DELIVERY' AND (p.id_cliente IS NULL OR p.id_endereco IS NULL))
   OR (cv.tipo='PRESENCIAL' AND p.id_endereco IS NOT NULL)
   OR (p.id_endereco IS NOT NULL AND (e.id_endereco IS NULL OR e.id_cliente<>p.id_cliente));

-- A12 — Existe desconto sem autorizacao de gerente ativo?
-- Verifica: RN13 (desconto autorizado).
SELECT p.id_pedido,p.desconto,p.id_autorizador_desconto,us.perfil
FROM pedidos p LEFT JOIN usuarios_sistema us ON us.id_usuario=p.id_autorizador_desconto
WHERE p.desconto>0 AND (us.id_usuario IS NULL OR us.perfil<>'GERENTE' OR us.ativo<>1);

-- A13 — Existe cancelamento sem autorizacao de gerente ativo?
-- Verifica: RN14 (cancelamento autorizado).
SELECT p.id_pedido,p.status,p.id_autorizador_cancelamento,us.perfil
FROM pedidos p LEFT JOIN usuarios_sistema us ON us.id_usuario=p.id_autorizador_cancelamento
WHERE p.status='CANCELADO' AND (us.id_usuario IS NULL OR us.perfil<>'GERENTE' OR us.ativo<>1);

-- A14 — Existem valores negativos ou precos e custos invalidos no cadastro?
-- Verifica: RN02 e RN15 (dominio monetario e de quantidades).
SELECT id_produto,nome,preco_venda,custo_unitario,estoque_atual
FROM produtos WHERE preco_venda<=0 OR custo_unitario<0 OR estoque_atual<0;

-- A15 — Existem pagamentos nao aprovados em valor superior ao total de pedido aberto,
--        ou pedido cancelado sem informacao de data de cancelamento?
-- Verifica: RN08 e RN15 (coerencia de status e valores).
SELECT p.id_pedido,p.status,p.total,p.cancelado_em
FROM pedidos p
WHERE (p.status='CANCELADO' AND p.cancelado_em IS NULL)
   OR (p.status<>'CANCELADO' AND p.cancelado_em IS NOT NULL)
   OR p.total<0;

-- A16 — Algum reembolso/estorno registrado excede o total do pedido cancelado?
-- Verifica: RN08 (integridade dos valores estornados).
SELECT p.id_pedido,p.total,SUM(pg.valor) AS valor_estornado
FROM pedidos p JOIN pagamentos pg ON pg.id_pedido=p.id_pedido
WHERE p.status='CANCELADO' AND pg.status='ESTORNADO'
GROUP BY p.id_pedido,p.total HAVING SUM(pg.valor)>p.total;

-- RESUMO DE VALIDACAO INICIAL (esperado: 900 pedidos, 1530 itens,
-- 893 pagamentos, 60 clientes, 16 produtos, 102 despesas, 0 divergencias
-- nas auditorias A01-A16 apos execucao em MySQL 8.0.16+).
SELECT (SELECT COUNT(*) FROM clientes) AS clientes,
       (SELECT COUNT(*) FROM produtos) AS produtos,
       (SELECT COUNT(*) FROM pedidos) AS pedidos,
       (SELECT COUNT(*) FROM itens_pedido) AS itens,
       (SELECT COUNT(*) FROM pagamentos) AS pagamentos,
       (SELECT COUNT(*) FROM despesas) AS despesas,
       (SELECT COUNT(*) FROM movimentacoes_estoque) AS movimentos;
